  "password" varchar(255) NOT NULL,
  "role" varchar NOT NULL DEFAULT 'employee' CHECK ("role" IN ('admin', 'employee')),
  "system_access" varchar NOT NULL DEFAULT 'employee' CHECK ("system_access" IN ('super_admin', 'admin', 'executive', 'hr', 'department_head', 'manager', 'team_lead', 'employee')),
  "project_access_override" varchar DEFAULT NULL CHECK ("project_access_override" IN ('granted', 'revoked')),
  "project_access_level" varchar NOT NULL DEFAULT 'basic' CHECK ("project_access_level" IN ('stakeholder', 'basic')),
  "employment_type" varchar NOT NULL DEFAULT 'employee' CHECK ("employment_type" IN ('employee', 'intern')),
  "status" varchar NOT NULL DEFAULT 'pending' CHECK ("status" IN ('pending', 'active', 'inactive')),
  "last_login" timestamp DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "organization_id" integer DEFAULT NULL,
  -- Tenant-wide highest authority -- exactly one TRUE row per tenant,
  -- enforced by the partial unique index below (not just by
  -- convention, unlike project_security_groups.is_default). Set ONLY
  -- by tenantUserService.createFirstAdmin() and the one-off backfill
  -- migration for pre-existing tenants -- no API/route ever writes
  -- this column. Deliberately independent of role/system_access: the
  -- project permission engine (services/projectPermissionService.js)
  -- checks this flag alone, never role='admin' or
  -- system_access='super_admin', so granting/promoting a Super Admin
  -- can never accidentally grant this authority.
  "is_system_administrator" boolean NOT NULL DEFAULT FALSE,
  -- Mandatory password change: TRUE for an account holding an administrator-issued temporary password.
  -- Cleared by the forced-change flow; password_changed_at (timestamptz, an unambiguous instant)
  -- rotates older sessions. See server/_migrate_add_must_change_password.js for existing databases.
  "must_change_password" boolean NOT NULL DEFAULT FALSE,
  "password_changed_at" timestamptz DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "employee_id" UNIQUE ("employee_id"),
  CONSTRAINT "email" UNIQUE ("email")
);

CREATE UNIQUE INDEX "uq_users_one_system_administrator" ON "users" ("is_system_administrator") WHERE "is_system_administrator" = TRUE;

CREATE TABLE "work_item_links" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "source_type" varchar  CHECK ("source_type" IN ('epic', 'feature', 'user_story', 'task')) NOT NULL,
  "source_id" integer NOT NULL,
  "target_type" varchar  CHECK ("target_type" IN ('epic', 'feature', 'user_story', 'task')) NOT NULL,
  "target_id" integer NOT NULL,
  "link_type" varchar  CHECK ("link_type" IN ('related', 'blocks')) NOT NULL,
  "project_id" integer NOT NULL,
  "created_by" integer NOT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "uniq_work_item_link" UNIQUE ("source_type","source_id","target_type","target_id","link_type")
);


