-- ==========================================
-- SMART SHEETS (collaborative spreadsheets)
--
-- Kept in sync, statement for statement, with schemas/smartSheetsDdl.js (the existing-tenant
-- migration source, which adds IF NOT EXISTS); _test_smart_sheets_migration.js fails if they
-- differ. No company_id -- tenant isolation is the tenant database itself.
-- ==========================================

CREATE TABLE "smart_sheets" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(150) NOT NULL,
  "status" varchar NOT NULL DEFAULT 'active' CHECK ("status" IN ('active', 'archived')),
  "revision" bigint NOT NULL DEFAULT 0,
  "cell_count" integer NOT NULL DEFAULT 0,
  "data_bytes" bigint NOT NULL DEFAULT 0,
  "source_file_name" varchar(255) DEFAULT NULL,
  "source_file_path" varchar(500) DEFAULT NULL,
  "created_by" integer DEFAULT NULL,
  "updated_by" integer DEFAULT NULL,
  "created_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted_at" timestamp NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "fk_smart_sheets_created_by" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_smart_sheets_updated_by" FOREIGN KEY ("updated_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "smart_sheet_access" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "sheet_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "permission" varchar NOT NULL DEFAULT 'edit' CHECK ("permission" IN ('view', 'edit')),
  "granted_by" integer DEFAULT NULL,
  "granted_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_smart_sheet_access_sheet_user" UNIQUE ("sheet_id", "user_id"),
  CONSTRAINT "fk_smart_sheet_access_sheet" FOREIGN KEY ("sheet_id") REFERENCES "smart_sheets" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_smart_sheet_access_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_smart_sheet_access_granted_by" FOREIGN KEY ("granted_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "smart_sheet_worksheets" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "sheet_id" integer NOT NULL,
  "ws_key" varchar(36) NOT NULL,
  "name" varchar(31) NOT NULL,
  "position" integer NOT NULL DEFAULT 0,
  "row_count" integer NOT NULL DEFAULT 1000,
  "column_count" integer NOT NULL DEFAULT 26,
  "layout" jsonb NOT NULL DEFAULT '{}'::jsonb,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_smart_sheet_worksheets_key" UNIQUE ("sheet_id", "ws_key"),
  CONSTRAINT "fk_smart_sheet_worksheets_sheet" FOREIGN KEY ("sheet_id") REFERENCES "smart_sheets" ("id") ON DELETE CASCADE
);

CREATE TABLE "smart_sheet_cells" (
  "worksheet_id" integer NOT NULL,
  "row_idx" integer NOT NULL,
  "col_idx" integer NOT NULL,
  "sheet_id" integer NOT NULL,
  "cell" jsonb NOT NULL,
  "bytes" integer NOT NULL DEFAULT 0,
  "revision" bigint NOT NULL DEFAULT 0,
  "updated_by" integer DEFAULT NULL,
  "updated_at" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("worksheet_id", "row_idx", "col_idx"),
  CONSTRAINT "fk_smart_sheet_cells_worksheet" FOREIGN KEY ("worksheet_id") REFERENCES "smart_sheet_worksheets" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_smart_sheet_cells_sheet" FOREIGN KEY ("sheet_id") REFERENCES "smart_sheets" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_smart_sheet_cells_updated_by" FOREIGN KEY ("updated_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE INDEX "idx_smart_sheets_status_deleted" ON "smart_sheets" ("status", "deleted_at");

CREATE INDEX "idx_smart_sheet_access_user" ON "smart_sheet_access" ("user_id");

CREATE INDEX "idx_smart_sheet_worksheets_sheet_position" ON "smart_sheet_worksheets" ("sheet_id", "position");

CREATE INDEX "idx_smart_sheet_cells_sheet" ON "smart_sheet_cells" ("sheet_id");

-- ==========================================
-- ZIOVAULT (client-side-encrypted password manager)
--
-- Kept in sync, statement for statement, with schemas/ziovaultDdl.js (the existing-tenant migration source, which makes
-- the statements re-runnable); _test_ziovault_schema.js fails if they differ. Every sensitive column is ciphertext or wrapped
-- key material. No company_id -- tenant isolation is the tenant database itself. Function bodies contain semicolons: the
-- provisioner uses utils/sqlStatements.js, which understands dollar-quoted bodies.
-- ==========================================

CREATE TABLE "zv_accounts" (
  "user_id" integer NOT NULL,
  "kdf_alg" varchar(16) NOT NULL DEFAULT 'argon2id13' CHECK ("kdf_alg" = 'argon2id13'),
  "kdf_ops" smallint NOT NULL CHECK ("kdf_ops" BETWEEN 2 AND 10),
  "kdf_mem" integer NOT NULL CHECK ("kdf_mem" BETWEEN 33554432 AND 268435456),
  "kdf_salt" bytea NOT NULL CHECK (octet_length("kdf_salt") = 16),
  "vault_key_envelope" bytea NOT NULL CHECK (octet_length("vault_key_envelope") = 73),
  "public_key" bytea NOT NULL CHECK (octet_length("public_key") = 32),
  "private_key_envelope" bytea NOT NULL CHECK (octet_length("private_key_envelope") = 73),
  "recovery_envelope" bytea NOT NULL CHECK (octet_length("recovery_envelope") = 73),
  "envelope_version" smallint NOT NULL DEFAULT 1,
  "account_version" integer NOT NULL DEFAULT 1,
  "recovery_confirmed_at" timestamptz NULL DEFAULT NULL,
  "password_changed_at" timestamptz NULL DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("user_id"),
  CONSTRAINT "uq_zv_accounts_public_key" UNIQUE ("public_key"),
  CONSTRAINT "fk_zv_accounts_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT
);

CREATE TABLE "zv_account_history" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "user_id" integer NOT NULL,
  "account_version" integer NOT NULL,
  "kdf_ops" smallint NOT NULL,
  "kdf_mem" integer NOT NULL,
  "kdf_salt" bytea NOT NULL,
  "vault_key_envelope" bytea NOT NULL CHECK (octet_length("vault_key_envelope") = 73),
  "reason" varchar(24) NOT NULL CHECK ("reason" IN ('password_changed', 'recovery_used', 'envelope_restored')),
  "replaced_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "fk_zv_account_history_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT
);

CREATE TABLE "zv_folders" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "uid" uuid NOT NULL,
  "owner_user_id" integer NOT NULL,
  "name_ciphertext" bytea NOT NULL CHECK (octet_length("name_ciphertext") BETWEEN 41 AND 2048),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_zv_folders_uid" UNIQUE ("uid"),
  CONSTRAINT "fk_zv_folders_owner" FOREIGN KEY ("owner_user_id") REFERENCES "users" ("id") ON DELETE RESTRICT
);

CREATE TABLE "zv_collections" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "uid" uuid NOT NULL,
  "kind" varchar(12) NOT NULL DEFAULT 'general' CHECK ("kind" IN ('general', 'department', 'project')),
  "name_ciphertext" bytea NOT NULL CHECK (octet_length("name_ciphertext") BETWEEN 41 AND 2048),
  "key_version" integer NOT NULL DEFAULT 1 CHECK ("key_version" >= 1),
  "rotation_required" boolean NOT NULL DEFAULT FALSE,
  "created_by" integer NULL DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "archived_at" timestamptz NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_zv_collections_uid" UNIQUE ("uid"),
  CONSTRAINT "fk_zv_collections_created_by" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "zv_collection_members" (
  "collection_id" integer NOT NULL,
  "user_id" integer NOT NULL,
  "can_reveal" boolean NOT NULL DEFAULT FALSE,
  "can_copy" boolean NOT NULL DEFAULT FALSE,
  "can_edit" boolean NOT NULL DEFAULT FALSE,
  "can_share" boolean NOT NULL DEFAULT FALSE,
  "is_manager" boolean NOT NULL DEFAULT FALSE,
  "wrapped_meta_key" bytea NOT NULL CHECK (octet_length("wrapped_meta_key") BETWEEN 73 AND 512),
  "wrapped_secret_key" bytea NULL DEFAULT NULL CHECK ("wrapped_secret_key" IS NULL OR octet_length("wrapped_secret_key") BETWEEN 73 AND 512),
  "sender_user_id" integer NOT NULL,
  "key_version" integer NOT NULL DEFAULT 1 CHECK ("key_version" >= 1),
  "expires_at" timestamptz NULL DEFAULT NULL,
  "added_by" integer NULL DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("collection_id", "user_id"),
  CONSTRAINT "ck_zv_members_secret_key_iff_reveal" CHECK (("can_reveal" = ("wrapped_secret_key" IS NOT NULL))),
  CONSTRAINT "ck_zv_members_rights_need_reveal" CHECK ((NOT "can_copy" OR "can_reveal") AND (NOT "can_edit" OR "can_reveal")),
  CONSTRAINT "ck_zv_members_manager_holds_everything" CHECK (NOT "is_manager" OR ("can_reveal" AND "can_edit" AND "can_share")),
  CONSTRAINT "fk_zv_members_collection" FOREIGN KEY ("collection_id") REFERENCES "zv_collections" ("id") ON DELETE RESTRICT,
  CONSTRAINT "fk_zv_members_user" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_members_sender" FOREIGN KEY ("sender_user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_members_added_by" FOREIGN KEY ("added_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "zv_items" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "uid" uuid NOT NULL,
  "owner_user_id" integer NULL DEFAULT NULL,
  "collection_id" integer NULL DEFAULT NULL,
  "folder_id" integer NULL DEFAULT NULL,
  "kind" varchar(16) NOT NULL DEFAULT 'login' CHECK ("kind" IN ('login', 'secure_note', 'api_key', 'other')),
  "meta_ciphertext" bytea NOT NULL CHECK (octet_length("meta_ciphertext") BETWEEN 41 AND 70000),
  "secret_ciphertext" bytea NULL DEFAULT NULL CHECK ("secret_ciphertext" IS NULL OR octet_length("secret_ciphertext") BETWEEN 41 AND 270000),
  "key_version" integer NOT NULL DEFAULT 1 CHECK ("key_version" >= 1),
  "version" integer NOT NULL DEFAULT 1 CHECK ("version" >= 1),
  "favorite" boolean NOT NULL DEFAULT FALSE,
  "rotation_interval_days" integer NULL DEFAULT NULL CHECK ("rotation_interval_days" IS NULL OR "rotation_interval_days" BETWEEN 1 AND 3650),
  "rotation_due_at" timestamptz NULL DEFAULT NULL,
  "last_rotated_at" timestamptz NOT NULL DEFAULT now(),
  "rotation_required" boolean NOT NULL DEFAULT FALSE,
  "reminder_sent_at" timestamptz NULL DEFAULT NULL,
  "deleted_at" timestamptz NULL DEFAULT NULL,
  "created_by" integer NULL DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_zv_items_uid" UNIQUE ("uid"),
  CONSTRAINT "ck_zv_items_personal_xor_company" CHECK (("owner_user_id" IS NULL) <> ("collection_id" IS NULL)),
  CONSTRAINT "ck_zv_items_folder_is_personal" CHECK ("folder_id" IS NULL OR "owner_user_id" IS NOT NULL),
  CONSTRAINT "fk_zv_items_owner" FOREIGN KEY ("owner_user_id") REFERENCES "users" ("id") ON DELETE RESTRICT,
  CONSTRAINT "fk_zv_items_collection" FOREIGN KEY ("collection_id") REFERENCES "zv_collections" ("id") ON DELETE RESTRICT,
  CONSTRAINT "fk_zv_items_folder" FOREIGN KEY ("folder_id") REFERENCES "zv_folders" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_zv_items_created_by" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "zv_item_keys" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "item_id" integer NOT NULL,
  "holder_type" varchar(12) NOT NULL CHECK ("holder_type" IN ('owner', 'user', 'collection')),
  "holder_user_id" integer NULL DEFAULT NULL,
  "purpose" varchar(8) NOT NULL CHECK ("purpose" IN ('meta', 'secret')),
  "wrapped_key" bytea NOT NULL CHECK (octet_length("wrapped_key") BETWEEN 73 AND 512),
  "sender_user_id" integer NULL DEFAULT NULL,
  "key_version" integer NOT NULL DEFAULT 1 CHECK ("key_version" >= 1),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id"),
  CONSTRAINT "ck_zv_item_keys_holder" CHECK (("holder_type" = 'collection') = ("holder_user_id" IS NULL)),
  CONSTRAINT "ck_zv_item_keys_sender" CHECK ("holder_type" <> 'user' OR "sender_user_id" IS NOT NULL),
  CONSTRAINT "fk_zv_item_keys_item" FOREIGN KEY ("item_id") REFERENCES "zv_items" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_item_keys_holder" FOREIGN KEY ("holder_user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_item_keys_sender" FOREIGN KEY ("sender_user_id") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "zv_grants" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "item_id" integer NOT NULL,
  "recipient_user_id" integer NOT NULL,
  "can_reveal" boolean NOT NULL DEFAULT FALSE,
  "can_copy" boolean NOT NULL DEFAULT FALSE,
  "can_edit" boolean NOT NULL DEFAULT FALSE,
  "can_share" boolean NOT NULL DEFAULT FALSE,
  "expires_at" timestamptz NULL DEFAULT NULL,
  "granted_by" integer NULL DEFAULT NULL,
  "parent_grant_id" integer NULL DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "updated_at" timestamptz NOT NULL DEFAULT now(),
  "revoked_at" timestamptz NULL DEFAULT NULL,
  "revoked_by" integer NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "ck_zv_grants_rights_need_reveal" CHECK ((NOT "can_copy" OR "can_reveal") AND (NOT "can_edit" OR "can_reveal")),
  CONSTRAINT "fk_zv_grants_item" FOREIGN KEY ("item_id") REFERENCES "zv_items" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_grants_recipient" FOREIGN KEY ("recipient_user_id") REFERENCES "users" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_grants_granted_by" FOREIGN KEY ("granted_by") REFERENCES "users" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_zv_grants_parent" FOREIGN KEY ("parent_grant_id") REFERENCES "zv_grants" ("id") ON DELETE SET NULL,
  CONSTRAINT "fk_zv_grants_revoked_by" FOREIGN KEY ("revoked_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "zv_attachments" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "uid" uuid NOT NULL,
  "item_id" integer NOT NULL,
  "meta_ciphertext" bytea NOT NULL CHECK (octet_length("meta_ciphertext") BETWEEN 41 AND 4096),
  "wrapped_file_key" bytea NOT NULL CHECK (octet_length("wrapped_file_key") = 73),
  "content" bytea NOT NULL CHECK (octet_length("content") BETWEEN 41 AND 10489856),
  "uploaded_by" integer NULL DEFAULT NULL,
  "created_at" timestamptz NOT NULL DEFAULT now(),
  "deleted_at" timestamptz NULL DEFAULT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "uq_zv_attachments_uid" UNIQUE ("uid"),
  CONSTRAINT "fk_zv_attachments_item" FOREIGN KEY ("item_id") REFERENCES "zv_items" ("id") ON DELETE CASCADE,
  CONSTRAINT "fk_zv_attachments_uploaded_by" FOREIGN KEY ("uploaded_by") REFERENCES "users" ("id") ON DELETE SET NULL
);

CREATE TABLE "zv_audit_events" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "kind" varchar(32) NOT NULL CHECK ("kind" IN ('account_created', 'envelopes_fetched', 'recovery_envelope_fetched', 'recovery_confirmed', 'password_changed', 'recovery_used', 'envelope_restored', 'recovery_rotated', 'item_created', 'item_updated', 'item_deleted', 'item_restored', 'item_rotated', 'secret_delivered', 'reveal_reported', 'copy_reported', 'item_shared', 'share_changed', 'share_revoked', 'access_expired', 'collection_created', 'collection_renamed', 'collection_archived', 'rotation_completed', 'rotation_reminded', 'vault_access_revoked', 'collection_member_added', 'collection_member_changed', 'collection_member_removed', 'collection_rotated', 'attachment_added', 'attachment_delivered', 'attachment_deleted', 'employee_deactivated')),
  "actor_user_id" integer NULL DEFAULT NULL,
  "subject_user_id" integer NULL DEFAULT NULL,
  "item_uid" uuid NULL DEFAULT NULL,
  "collection_uid" uuid NULL DEFAULT NULL,
  "detail" varchar(120) NOT NULL DEFAULT '' CHECK ("detail" ~ '^[a-z0-9_.:,=-]*$'),
  "created_at" timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "uq_zv_item_keys_holder" ON "zv_item_keys" ("item_id", "holder_type", COALESCE("holder_user_id", 0), "purpose");

CREATE UNIQUE INDEX "uq_zv_grants_active" ON "zv_grants" ("item_id", "recipient_user_id") WHERE "revoked_at" IS NULL;

CREATE INDEX "idx_zv_items_owner" ON "zv_items" ("owner_user_id") WHERE "deleted_at" IS NULL;

CREATE INDEX "idx_zv_items_collection" ON "zv_items" ("collection_id") WHERE "deleted_at" IS NULL;

CREATE INDEX "idx_zv_items_rotation_due" ON "zv_items" ("last_rotated_at") WHERE "rotation_interval_days" IS NOT NULL AND "deleted_at" IS NULL;

CREATE INDEX "idx_zv_item_keys_holder_user" ON "zv_item_keys" ("holder_user_id") WHERE "holder_user_id" IS NOT NULL;

CREATE INDEX "idx_zv_grants_recipient" ON "zv_grants" ("recipient_user_id") WHERE "revoked_at" IS NULL;

CREATE INDEX "idx_zv_grants_expiry" ON "zv_grants" ("expires_at") WHERE "revoked_at" IS NULL AND "expires_at" IS NOT NULL;

CREATE INDEX "idx_zv_grants_parent" ON "zv_grants" ("parent_grant_id");

CREATE INDEX "idx_zv_members_user" ON "zv_collection_members" ("user_id");

CREATE INDEX "idx_zv_attachments_item" ON "zv_attachments" ("item_id") WHERE "deleted_at" IS NULL;

CREATE INDEX "idx_zv_audit_item" ON "zv_audit_events" ("item_uid", "created_at");

CREATE INDEX "idx_zv_audit_subject" ON "zv_audit_events" ("subject_user_id", "created_at");

CREATE INDEX "idx_zv_audit_collection" ON "zv_audit_events" ("collection_uid", "created_at");

CREATE OR REPLACE FUNCTION zv_audit_immutable() RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION 'zv_audit_events is append-only';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "zv_audit_no_update" BEFORE UPDATE OR DELETE ON "zv_audit_events" FOR EACH ROW EXECUTE FUNCTION zv_audit_immutable();

CREATE TRIGGER "zv_audit_no_truncate" BEFORE TRUNCATE ON "zv_audit_events" FOR EACH STATEMENT EXECUTE FUNCTION zv_audit_immutable();

CREATE OR REPLACE FUNCTION zv_revoke_grants(p_seed integer[], p_actor integer, p_reason text) RETURNS integer AS $$
DECLARE
  revoked_count integer;
BEGIN
  WITH RECURSIVE doomed(id) AS (
    SELECT g.id FROM zv_grants g WHERE g.id = ANY(p_seed) AND g.revoked_at IS NULL
    UNION
    SELECT g.id FROM zv_grants g JOIN doomed d ON g.parent_grant_id = d.id WHERE g.revoked_at IS NULL
  ),
  revoked AS (
    UPDATE zv_grants g SET revoked_at = now(), revoked_by = p_actor, updated_at = now()
    WHERE g.id IN (SELECT id FROM doomed) AND g.revoked_at IS NULL
    RETURNING g.id, g.item_id, g.recipient_user_id, g.can_reveal
  ),
  removed_keys AS (
    DELETE FROM zv_item_keys k USING revoked r
    WHERE k.item_id = r.item_id AND k.holder_type = 'user' AND k.holder_user_id = r.recipient_user_id
    RETURNING k.id
  ),
  flagged AS (
    UPDATE zv_items i SET rotation_required = TRUE
    FROM revoked r WHERE i.id = r.item_id AND r.can_reveal
    RETURNING i.id
  ),
  audited AS (
    INSERT INTO zv_audit_events (kind, actor_user_id, subject_user_id, item_uid, detail)
    SELECT CASE WHEN p_reason = 'expired' THEN 'access_expired' ELSE 'share_revoked' END, p_actor, r.recipient_user_id, i.uid, 'reason=' || p_reason
    FROM revoked r JOIN zv_items i ON i.id = r.item_id
    RETURNING id
  )
  SELECT count(*) INTO revoked_count FROM revoked;
  RETURN revoked_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION zv_remove_collection_members(p_collection integer, p_users bigint[], p_actor integer, p_reason text) RETURNS integer AS $$
DECLARE
  removed_count integer;
BEGIN
  WITH gone AS (
    DELETE FROM zv_collection_members m
    WHERE (p_collection IS NULL OR m.collection_id = p_collection) AND m.user_id = ANY(p_users)
    RETURNING m.collection_id, m.user_id
  ),
  flagged AS (
    UPDATE zv_collections c SET rotation_required = TRUE, updated_at = now()
    WHERE c.id IN (SELECT collection_id FROM gone)
    RETURNING c.id
  ),
  audited AS (
    INSERT INTO zv_audit_events (kind, actor_user_id, subject_user_id, collection_uid, detail)
    SELECT CASE WHEN p_reason = 'expired' THEN 'access_expired' ELSE 'collection_member_removed' END, p_actor, gone.user_id, c.uid, 'reason=' || p_reason
    FROM gone JOIN zv_collections c ON c.id = gone.collection_id
    RETURNING id
  )
  SELECT count(*) INTO removed_count FROM gone;
  RETURN removed_count;
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION zv_offboard_user() RETURNS trigger AS $$
DECLARE
  removed_count integer;
  revoked_count integer;
  seed integer[];
BEGIN
  removed_count := zv_remove_collection_members(NULL, ARRAY[NEW.id]::bigint[], NULL, 'offboarding');

  SELECT COALESCE(array_agg(g.id), '{}'::integer[]) INTO seed
  FROM zv_grants g JOIN zv_items i ON i.id = g.item_id
  WHERE g.revoked_at IS NULL AND (g.recipient_user_id = NEW.id OR i.owner_user_id = NEW.id);

  revoked_count := zv_revoke_grants(seed, NULL, 'offboarding');

  INSERT INTO zv_audit_events (kind, actor_user_id, subject_user_id, detail)
  VALUES ('employee_deactivated', NULL, NEW.id, 'members_removed=' || removed_count::text || ',revoked_grants=' || revoked_count::text);

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "zv_offboard_on_users_update" AFTER UPDATE OF "status", "employment_status" ON "users" FOR EACH ROW WHEN (OLD."status" = 'active' AND COALESCE(OLD."employment_status", 'active') = 'active' AND (NEW."status" <> 'active' OR COALESCE(NEW."employment_status", 'active') <> 'active')) EXECUTE FUNCTION zv_offboard_user();
